{"content":""""Extract inventory fields from a pickle WITHOUT executing it.

Mini stack machine over pickletools.genops. Only literal/safe opcodes are
honored; anything that could invoke code (GLOBAL, STACK_GLOBAL, REDUCE,
BUILD, NEWOBJ, INST, EXT*, CALL, ...) is rejected before it is ever touched.
"""

import sys
import pickletools

MARK = object()

# Opcodes that push literals or do pure stack/memo bookkeeping.
SAFE = {
    "PROTO", "FRAME", "STOP",
    "EMPTY_DICT", "EMPTY_LIST", "EMPTY_TUPLE", "EMPTY_SET", "EMPTY_FROZENSET",
    "MARK", "MEMOIZE", "POP", "POP_MARK", "DUP",
    "NONE", "TRUE", "FALSE",
    "SHORT_BINUNICODE", "BINUNICODE", "UNICODE", "SHORT_BINBYTES", "BINBYTES", "BYTEARRAY8",
    "SHORT_ASCII", "SHORT_ASCII_STRING", "BINASCII",
    "BININT1", "BININT2", "BININT4", "INT", "LONG1", "LONG4", "FLOAT", "BINFLOAT",
    "APPEND", "APPENDS", "SETITEM", "SETITEMS", "LISTITEMS", "DICTITEMS",
    "TUPLE", "TUPLE1", "TUPLE2", "TUPLE3",
    "ADDITEMS", "FROZENSETITEMS", "MEMOIZE", "NEWFALSE", "NEWTRUE", "NEWOBJ_MEMO",
    "PERSID", "BINPERSID",  # no persistent_load hook installed -> load would fail; reject too
}

PERSID = {"PERSID", "BINPERSID"}


def safe_load(path):
    with open(path, "rb") as f:
        data = f.read()
    stack = []
    memo = {}
    for op, arg, _pos in pickletools.genops(data):
        name = op.name
        if name in ("GLOBAL", "STACK_GLOBAL", "REDUCE", "BUILD", "INST", "OBJ",
                    "NEWOBJ", "NEWOBJ_EX", "CALL", "CALL_FUNCTION_EX",
                    "EXT1", "EXT2", "EXT4") or name in PERSID or name not in SAFE:
            raise ValueError(f"unsafe/unsupported opcode: {name}")
        if name == "MARK":
            stack.append(MARK)
        elif name in ("EMPTY_DICT",):
            stack.append({})
        elif name in ("EMPTY_LIST",):
            stack.append([])
        elif name in ("EMPTY_TUPLE",):
            stack.append(())
        elif name in ("EMPTY_SET",):
            stack.append(set())
        elif name in ("EMPTY_FROZENSET",):
            stack.append(frozenset())
        elif name in ("NONE",):
            stack.append(None)
        elif name in ("TRUE", "NEWTRUE"):
            stack.append(True)
        elif name in ("FALSE", "NEWFALSE"):
            stack.append(False)
        elif name in ("SHORT_BINUNICODE", "BINUNICODE", "UNICODE",
                      "SHORT_ASCII", "SHORT_ASCII_STRING", "BINASCII"):
            stack.append(arg)
        elif name in ("SHORT_BINBYTES", "BINBYTES", "BYTEARRAY8"):
            stack.append(arg)
        elif name in ("BININT1", "BININT2", "BININT4", "INT", "LONG1", "LONG4",
                      "FLOAT", "BINFLOAT"):
            stack.append(arg)
        elif name == "MEMOIZE":
            memo[len(memo)] = stack[-1]
        elif name == "POP":
            stack.pop()
        elif name == "POP_MARK":
            while stack.pop() is not MARK:
                pass
        elif name == "DUP":
            stack.append(stack[-1])
        elif name == "APPEND":
            value = stack.pop()
            stack[-1].append(value)
        elif name == "APPENDS":
            items = []
            while True:
                item = stack.pop()
                if item is MARK:
                    break
                items.append(item)
            items.reverse()
            stack[-1].extend(items)
        elif name == "SETITEM":
            value = stack.pop()
            key = stack.pop()
            stack[-1][key] = value
        elif name == "SETITEMS":
            items = []
            while True:
                item = stack.pop()
                if item is MARK:
                    break
                items.append(item)
            items.reverse()
            d = stack[-1]
            for i in range(0, len(items), 2):
                d[items[i]] = items[i + 1]
        elif name in ("TUPLE1", "TUPLE2", "TUPLE3"):
            n = int(name[-1])
            stack[-n:] = [tuple(stack[-n:])]
        elif name == "TUPLE":
            items = []
            while True:
                item = stack.pop()
                if item is MARK:
                    break
                items.append(item)
            items.reverse()
            stack.append(tuple(items))
        elif name in ("PROTO", "FRAME", "STOP"):
            if name == "STOP":
                return stack.pop()
    raise ValueError("truncated pickle (no STOP)")


if __name__ == "__main__":
    d = safe_load(sys.argv[1])
    print(repr(d))
